    "rules": {
      "body":
          "one region letter, one encoded gender digit, seven synthetic serial digits",
      "canonical_pattern": "^[A-Z][12][0-9]{8}\$",
      "check_digits": 1,
      "checksum": {
        "check_weight": 1,
        "eight_body_digit_weights": [8, 7, 6, 5, 4, 3, 2, 1],
        "generation_formula":
            "S = tens(letter_value) + 9*units(letter_value) + dot(eight_body_digits,[8,7,6,5,4,3,2,1]); c = (10-(S%10))%10",
        "letter_expansion_weights": [1, 9],
        "modulus": 10,
        "source_id": "TW-CHECK-2023",
        "source_physical_pdf_page_1_based": 179,
        "source_printed_page": "第四章 附則(附件)-21",
        "status": "official_published_method",
        "validation_formula": "(S + check_digit) % 10 == 0",
      },
      "country_key": "CN",
      "current_region_count": 22,
      "default_generation_region_file": "tw-regions.json",
      "document": "National identification card uniform identification number",
